mapper.update:
UPDATE outbox SET status = 'PENDING'
WHERE status = 'SENDING'
  AND next_attempt_at < #{now}

mapper.select:
SELECT id, event_key, topic, payload, attempts
FROM outbox
WHERE status = 'PENDING'
  AND next_attempt_at <= #{now}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE outbox
   SET status = 'SENDING', attempts = attempts + 1, next_attempt_at = #{leaseUntil}
 WHERE id = #{id}
   AND status = 'PENDING'

UPDATE outbox
   SET status = #{status}, last_error = #{error}, next_attempt_at = #{nextAttempt}
 WHERE id = #{id}

mapper.select:
SELECT id, submission_id, verdict, message,
       DATE_FORMAT(created_at, '%Y-%m-%dT%H:%i:%s') AS created_at
FROM notifications

    WHERE user_id = #{userId}

ORDER BY id DESC
LIMIT #{limit}
